import{_ as s,o as i,c as e,a2 as t}from"./chunks/framework.CTeY_0bQ.js";const k=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1793891960000}'),l={name:"guide/getting-started.md"};function d(p,a,o,h,n,c){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>从安装到第一个需求，大约 15 分钟。每台机器只需安装一次，装在运行 agent 平台（Paseo 或 DeepSeek Harness）的那台机器上。</p><h2 id="_1-安装" tabindex="-1">1. 安装 <a class="header-anchor" href="#_1-安装" aria-label="Permalink to &quot;1. 安装&quot;">​</a></h2><p>只需要 Node.js 22.19+ 和能访问的 npm 源：</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-NRMPI" id="tab-GpxiahM" checked><label data-title="DeepSeek Harness" for="tab-GpxiahM">DeepSeek Harness</label><input type="radio" name="group-NRMPI" id="tab-Omkpp4d"><label data-title="Paseo" for="tab-Omkpp4d">Paseo</label><input type="radio" name="group-NRMPI" id="tab-IjzhnU2"><label data-title="公司内网（npm 镜像）" for="tab-IjzhnU2">公司内网（npm 镜像）</label></div><div class="blocks"><div class="language-sh vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @yiyi_zhang/laoshi@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --platform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dsh</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @yiyi_zhang/laoshi@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --platform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> paseo</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --registry=https://npm.example.internal/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @yiyi_zhang/laoshi@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --platform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dsh</span></span></code></pre></div></div></div><p>Windows 上在 cmd 或 Git Bash 中运行即可，不需要 PowerShell，也不需要管理员权限。公司内网只有 npm 镜像时，用 <code>--registry</code> 写上镜像地址，它会保存为本机的 npm 源，以后 <code>laoshi upgrade</code> 也从镜像取。</p><p>安装会依次：</p><ol><li>检查 Node.js、npm 和 git，确定 npm 源；</li><li>从 npm 安装 <code>laoshi</code>（npm 全局目录不可写时装到 <code>~/.laoshi/npm</code>，不需要 sudo）；</li><li>写好安装根 <code>~/.laoshi</code> 和安装级配置（平台、各角色用的模型）；</li><li>把 <code>/laoshi</code> 等 skill 按平台渲染后装进平台的 skill 目录（不覆盖别人放的同名 skill）；</li><li>做平台需要的设置：dsh 上安装并挂载 laoshi 的 dsh 插件；</li><li>在 <code>~/.laoshi/bin</code> 中放好 <code>laoshi</code> 命令。</li></ol><p>再次运行同一条命令即升级（或运行 <code>laoshi upgrade</code>）。装好后运行 <code>laoshi docs</code> 可以在本机打开这份文档（和装的版本一致，不需要外网）。</p><div class="tip custom-block"><p class="custom-block-title">没有 npm 源时</p><p>完全离线的机器用带依赖的离线安装包，见 <a href="./intranet">内网安装与验证</a>。各项选项见 <a href="./install">安装与升级</a>。</p></div><h2 id="_2-体检" tabindex="-1">2. 体检 <a class="header-anchor" href="#_2-体检" aria-label="Permalink to &quot;2. 体检&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">laoshi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-project</span></span></code></pre></div><p>它检查安装、配置、平台（Paseo daemon 或 dsh 插件）、各角色的模型。全部是 ✓ 或只有 ⚠ 即可继续；✗ 的项按提示处理。</p><details class="details custom-block"><summary><code>laoshi</code> 命令找不到？</summary><p>npm 的全局目录不在 PATH 中时，使用安装根中的命令：<code>~/.laoshi/bin/laoshi</code>（Windows 上是 <code>%USERPROFILE%\\.laoshi\\bin\\laoshi.cmd</code>），或把那个目录加进 PATH。</p></details><h2 id="_3-接入项目-每个项目一次" tabindex="-1">3. 接入项目（每个项目一次） <a class="header-anchor" href="#_3-接入项目-每个项目一次" aria-label="Permalink to &quot;3. 接入项目（每个项目一次）&quot;">​</a></h2><p>在平台中打开项目主目录（最好在主分支上），新开对话，输入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/laoshi-setup</span></span></code></pre></div><p>agent 会读项目、只问读不出来的事、把安装依赖/测试/启动服务的命令实际跑一遍，然后生成并请你确认这些文件：</p><table tabindex="0"><thead><tr><th>文件</th><th>作用</th></tr></thead><tbody><tr><td><code>.requirement-pipeline/project-notes.md</code></td><td>项目约定：包管理工具、不能改的目录、提交格式</td></tr><tr><td><code>.requirement-pipeline/verify.md</code></td><td>验证方法：实际跑通的安装、测试、启动命令</td></tr><tr><td><code>paseo.json</code>（Paseo）或 <code>.laoshi/services.json</code>（dsh 等）</td><td>新建工作区时自动准备环境；服务由平台或 laoshi 托管，每个工作区独立端口</td></tr></tbody></table><h2 id="_4-提第一个需求" tabindex="-1">4. 提第一个需求 <a class="header-anchor" href="#_4-提第一个需求" aria-label="Permalink to &quot;4. 提第一个需求&quot;">​</a></h2><p>在项目的对话中输入 <code>/laoshi</code> 和一句话：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/laoshi 登录页增加短信验证码登录</span></span></code></pre></div><p>接下来：</p><ol><li>AI 复述理解，一次问一个问题；拿不准时说&quot;你定&quot;。</li><li>标准档会请另一个模型独立审阅需求说明，把发现的问题逐个问你。</li><li>确认需求说明后，选择现在开始或预约时间（例如今晚 10 点）。</li><li>开发在后台进行，每一步都出现在对话的子 agent 列表中；你会收到几句进展。</li><li>完成后收到结论和报告，说&quot;我要验收&quot;，按验收标准逐条核对。</li></ol><div class="tip custom-block"><p class="custom-block-title">从一个小需求开始</p><p>第一次建议用一个范围很小的改动（例如改一段文案），走快速档，十几分钟就能看到完整的流程。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./user">使用者指南</a>：过程中可以说什么、会收到哪些通知、怎么验收。</li><li><a href="./how-it-works">工作原理</a>：流水线的每一步做什么、产物在哪里。</li><li><a href="./project">项目定制与运行规则</a>：档位、评审小组、分阶段执行、通知等配置。</li></ul>',27)])])}const g=s(l,[["render",d]]);export{k as __pageData,g as default};
